import type { Declaration, Root } from "postcss";
import type { PostcssResult } from "stylelint";
import type { Syntax } from "../../syntaxes/index.ts";
/** Checks the whitespace at one index. */
export type LocationChecker = (args: {
    source: string;
    index: number;
    lineCheckStr: string;
    err: (message: string) => void;
}) => void;
/**
 * Checks the whitespace beside the colon of every declaration.
 * @param opts - The options.
 */
export declare function declarationColonSpaceChecker(opts: {
    root: Root;
    locationChecker: LocationChecker;
    fix?: ((decl: Declaration, index: number, run: string) => void);
    isChecked?: ((decl: Declaration) => boolean);
    isFixable?: ((decl: Declaration, index: number, source: string, runString: string) => boolean);
    result: PostcssResult;
    syntax: Syntax;
    checkedRuleName: string;
}): void;
